// Ready-to-run example programs. They are generated by small "CAM" routines so the geometry is exact
// (tangent arcs, offsets, helices), and emitted in the style of a Fanuc/Haas post-processor.
// Every example assumes the part zero (G54) at the top centre of the stock, which the simulator sets
// up automatically when the example is loaded.

const f = (v) => {
  let s = (Math.round(v * 1000) / 1000).toFixed(3).replace(/0+$/, '');
  if (s === '-0.') s = '0.';
  return s;
};

class Prog {
  constructor() {
    this.out = [];
    this.n = 0;
  }
  l(...parts) {
    this.out.push(parts.filter((p) => p !== '' && p != null).join(' '));
    return this;
  }
  c(text) {
    return this.l(`(${text.toUpperCase()})`);
  }
  blank() {
    this.out.push('');
    return this;
  }
  seq(text) {
    this.n += 10;
    return this.l(`N${this.n}`, text ? `(${text.toUpperCase()})` : '');
  }
  toString() {
    return this.out.join('\n') + '\n';
  }
}

function header(p, num, title, stock, tools) {
  p.l('%');
  p.l(`O${num}`, `(${title.toUpperCase()})`);
  p.c(`Stock ${stock.x} x ${stock.y} x ${stock.z} mm ${stock.label}`);
  p.c('Part zero G54: top centre of stock');
  for (const t of tools) p.c(t);
  p.l('G90 G94 G17 G21 G40 G49 G80');
  p.l('G54');
}

function footer(p) {
  p.l('G00 Z25. M09');
  p.l('M05');
  p.l('G91 G28 Z0.');
  p.l('G28 X0. Y0.');
  p.l('G90');
  p.l('M30');
  p.l('%');
}

function toolStart(p, t, h, s, x, y, desc) {
  p.seq(desc);
  p.l(`T${t}`, 'M06');
  p.l(`S${s}`, 'M03');
  p.l('G00', 'G54', `X${f(x)}`, `Y${f(y)}`);
  p.l('G43', `H${String(h).padStart(2, '0')}`, 'Z25.', 'M08');
}

function toolEnd(p) {
  p.l('G00 Z25.');
  p.l('M09');
  p.l('M05');
  p.l('G91 G28 Z0.');
  p.l('G90');
}

// ---------------------------------------------------------------------------------------------
function facing() {
  const p = new Prog();
  const stock = { x: 120, y: 80, z: 30, label: 'aluminium 6061' };
  header(p, 1001, 'Facing - 50 mm face mill', stock, ['T1 face mill D50 5 inserts']);
  toolStart(p, 1, 1, 3200, -90, -25, 'Face top 1.0 mm in two passes');
  p.l('Z2.');
  const ys = [-25, 0, 25];
  for (const z of [-0.5, -1.0]) {
    p.c(`Pass depth Z${f(z)}`);
    p.l('G00', 'X-90.', `Y${f(ys[0])}`);
    p.l('G01', `Z${f(z)}`, 'F800.');
    let dir = 1;
    for (let i = 0; i < ys.length; i++) {
      p.l('G01', `X${f(90 * dir)}`, 'F1300.');
      if (i < ys.length - 1) p.l(`Y${f(ys[i + 1])}`);
      dir = -dir;
    }
    p.l('G00 Z2.');
  }
  toolEnd(p);
  p.l('M30');
  p.l('%');
  return { code: p.toString(), stock: { x: 120, y: 80, z: 30, material: 'aluminium', protrusion: 14 } };
}

// ---------------------------------------------------------------------------------------------
function rectPocket() {
  const p = new Prog();
  const stock = { x: 120, y: 80, z: 30, label: 'aluminium 6061' };
  header(p, 1002, 'Rectangular pocket 70 x 44 x 6 deep', stock, ['T2 flat end mill D10 3FL']);
  const R = 5;
  const A = 35 - R, B = 22 - R; // tool-centre half sizes of the finished wall
  const step = 6;
  const rings = [];
  for (let i = 0; ; i++) {
    const a = A - i * step, b = B - i * step;
    if (b <= 0) break;
    rings.push([a, b]);
  }
  rings.reverse(); // inside out
  const [a0] = rings[0];
  toolStart(p, 2, 2, 9500, -a0 + 6, 0, 'Rough pocket in 2 mm steps, ramp entry');
  p.l('Z2.');
  p.l('G01 Z0.5 F700.');
  let z = 0.5;
  for (const depth of [-2, -4, -6]) {
    p.c(`Level Z${f(depth)}`);
    // zig-zag ramp along the centre line, about 4 degrees
    const rx = a0 - 6;
    p.l('G01', `X${f(-rx)}`, 'Y0.', 'F700.');
    p.l(`X${f(rx)}`, `Z${f((z + depth) / 2)}`);
    p.l(`X${f(-rx)}`, `Z${f(depth)}`);
    p.l(`X${f(rx)}`);
    z = depth;
    p.l('F1400.');
    for (const [a, b] of rings) {
      p.l('G01', `X${f(a)}`, 'Y0.');
      p.l(`Y${f(b)}`);
      p.l(`X${f(-a)}`);
      p.l(`Y${f(-b)}`);
      p.l(`X${f(a)}`);
      p.l('Y0.');
    }
    p.l('G01', `X${f(-a0 + 6)}`, 'Y0.');
  }
  p.c('Finish wall, corner radius 6');
  const r = 1; // tool-centre corner radius = 6 - 5
  p.l('G01', `X${f(A - 3)}`, 'Y0.', 'F1000.');
  p.l('G03', `X${f(A)}`, `Y${f(3)}`, 'R3.');
  p.l('G01', `Y${f(B - r)}`);
  p.l('G03', `X${f(A - r)}`, `Y${f(B)}`, `R${f(r)}`);
  p.l('G01', `X${f(-A + r)}`);
  p.l('G03', `X${f(-A)}`, `Y${f(B - r)}`, `R${f(r)}`);
  p.l('G01', `Y${f(-B + r)}`);
  p.l('G03', `X${f(-A + r)}`, `Y${f(-B)}`, `R${f(r)}`);
  p.l('G01', `X${f(A - r)}`);
  p.l('G03', `X${f(A)}`, `Y${f(-B + r)}`, `R${f(r)}`);
  p.l('G01', `Y${f(3)}`);
  p.l('G03', `X${f(A - 3)}`, 'Y6.', 'R3.');
  toolEnd(p);
  p.l('M30');
  p.l('%');
  return { code: p.toString(), stock: { x: 120, y: 80, z: 30, material: 'aluminium', protrusion: 14 } };
}

// ---------------------------------------------------------------------------------------------
function circPocket() {
  const p = new Prog();
  const stock = { x: 100, y: 100, z: 30, label: 'brass C360' };
  header(p, 1003, 'Circular pocket D56 x 8 deep, helical entry', stock, ['T2 flat end mill D10 3FL']);
  const rings = [4, 10, 16, 23];
  toolStart(p, 2, 2, 7000, 4, 0, 'Helical entry and spiral-out rings');
  p.l('Z2.');
  p.l('G01 Z0.5 F600.');
  let z = 0.5;
  for (const depth of [-2.5, -5, -7.5, -8]) {
    p.c(`Level Z${f(depth)}`);
    p.l('G01', 'X4.', 'Y0.', 'F600.');
    // helix down at 1 mm per revolution
    while (z > depth + 1e-9) {
      z = Math.max(depth, z - 1);
      p.l('G03', 'X4.', 'Y0.', `Z${f(z)}`, 'I-4.', 'J0.');
    }
    p.l('G03', 'X4.', 'Y0.', 'I-4.', 'J0.', 'F900.');
    for (const r of rings.slice(1)) {
      p.l('G01', `X${f(r)}`, 'Y0.');
      p.l('G03', `X${f(r)}`, 'Y0.', `I${f(-r)}`, 'J0.');
    }
  }
  p.c('Finish pass with tangent arc lead-in');
  const rf = 23;
  p.l('G01', 'X13.', 'Y0.', 'F700.');
  p.l('G03', `X${f(rf)}`, 'Y0.', 'R5.');
  p.l('G03', `X${f(rf)}`, 'Y0.', `I${f(-rf)}`, 'J0.');
  p.l('G03', 'X13.', 'Y0.', 'R5.');
  p.l('G01 X0. Y0.');
  toolEnd(p);
  p.l('M30');
  p.l('%');
  return { code: p.toString(), stock: { x: 100, y: 100, z: 30, material: 'brass', protrusion: 14 } };
}

// ---------------------------------------------------------------------------------------------
function drilling() {
  const p = new Prog();
  const stock = { x: 120, y: 80, z: 25, label: 'steel 1045' };
  header(p, 1004, 'Drilling pattern - bolt circle and corners', stock, ['T4 spot drill D10 90 deg', 'T5 drill D6.8 118 deg']);
  const bolt = [];
  for (let i = 0; i < 6; i++) {
    const a = (i * Math.PI) / 3;
    bolt.push([25 * Math.cos(a), 25 * Math.sin(a)]);
  }
  const corners = [[-48, -28], [48, -28], [48, 28], [-48, 28]];
  toolStart(p, 4, 4, 2400, bolt[0][0], bolt[0][1], 'Spot drill all holes, G81 and G82');
  p.l('G99', 'G81', `X${f(bolt[0][0])}`, `Y${f(bolt[0][1])}`, 'Z-3.6', 'R2.', 'F240.');
  for (const [x, y] of bolt.slice(1)) p.l(`X${f(x)}`, `Y${f(y)}`);
  p.l('G82', `X${f(corners[0][0])}`, `Y${f(corners[0][1])}`, 'Z-4.2', 'R2.', 'P300', 'F240.');
  for (let i = 1; i < corners.length; i++) p.l(i === corners.length - 1 ? 'G98' : '', `X${f(corners[i][0])}`, `Y${f(corners[i][1])}`);
  p.l('G80');
  toolEnd(p);
  p.blank();
  toolStart(p, 5, 5, 1400, bolt[0][0], bolt[0][1], 'Peck drill D6.8 x 18 deep, G83');
  p.l('G99', 'G83', `X${f(bolt[0][0])}`, `Y${f(bolt[0][1])}`, 'Z-18.', 'R2.', 'Q4.', 'F150.');
  for (const [x, y] of bolt.slice(1)) p.l(`X${f(x)}`, `Y${f(y)}`);
  p.c('Corners with high-speed peck G73');
  p.l('G73', `X${f(corners[0][0])}`, `Y${f(corners[0][1])}`, 'Z-15.', 'R2.', 'Q2.5', 'F150.');
  for (let i = 1; i < corners.length; i++) p.l(i === corners.length - 1 ? 'G98' : '', `X${f(corners[i][0])}`, `Y${f(corners[i][1])}`);
  p.l('G80');
  toolEnd(p);
  p.l('M30');
  p.l('%');
  return { code: p.toString(), stock: { x: 120, y: 80, z: 25, material: 'steel', protrusion: 14 } };
}

// ---------------------------------------------------------------------------------------------
function slots() {
  const p = new Prog();
  const stock = { x: 120, y: 80, z: 25, label: 'acetal POM' };
  header(p, 1005, 'Slot milling - straight and arc slots', stock, ['T3 flat end mill D6 3FL']);
  toolStart(p, 3, 3, 10000, -40, 25, 'Straight slots 6 wide x 4 deep, 1 mm per pass');
  p.l('Z2.');
  const levels = [-1, -2, -3, -4];
  for (const y of [25, -25]) {
    p.c(`Slot at Y${f(y)}`);
    p.l('G00', 'X-40.', `Y${f(y)}`);
    p.l('G01', 'Z0.2', 'F400.');
    let x = -40;
    for (const z of levels) {
      p.l('G01', `Z${f(z)}`, 'F250.');
      x = -x;
      p.l('G01', `X${f(x)}`, 'F1500.');
    }
    p.l('G00 Z2.');
  }
  p.seq('Arc slot R50 through X-35 Y0 / X35 Y0');
  p.l('G00', 'X-35.', 'Y0.');
  p.l('G01', 'Z0.2', 'F400.');
  let fwd = true;
  for (const z of levels) {
    p.l('G01', `Z${f(z)}`, 'F250.');
    if (fwd) p.l('G02', 'X35.', 'Y0.', 'R50.', 'F1500.');
    else p.l('G03', 'X-35.', 'Y0.', 'R50.', 'F1500.');
    fwd = !fwd;
  }
  p.l('G00 Z2.');
  p.seq('Keyway slot along Y using incremental moves');
  p.l('G00', 'X0.', 'Y-14.');
  p.l('G01', 'Z0.2', 'F400.');
  p.l('G91');
  for (let i = 0; i < 4; i++) {
    p.l('G01', 'Z-1.2', 'F250.');
    p.l('G01', `Y${i % 2 ? '-12.' : '12.'}`, 'F1500.');
  }
  p.l('G90');
  toolEnd(p);
  p.l('M30');
  p.l('%');
  return { code: p.toString(), stock: { x: 120, y: 80, z: 25, material: 'plastic', protrusion: 14 } };
}

// ---------------------------------------------------------------------------------------------
// Outside profile of a bracket: tangent corner arcs, a concave notch and a large end radius.
// Part outline (clockwise): top line, R10 corner, right side with an R8 notch, R10 corner,
// bottom line, R30 end round. The tool-centre path is offset outward by the tool radius.
function contourRing(p, d, withNotch, first) {
  const X = (v) => f(v + 10);
  // start on the top line, travelling right (clockwise around the part = climb milling)
  if (first) p.l('G01', `X${X(-20)}`, `Y${f(30 + d)}`);
  p.l('G01', `X${X(20)}`, `Y${f(30 + d)}`);
  p.l('G02', `X${X(30 + d)}`, 'Y20.', `I0.`, `J${f(-(10 + d))}`);
  if (withNotch && d < 8) {
    p.l('G01', `Y8.`);
    p.l('G02', `X${X(30)}`, `Y${f(8 - d)}`, `I${f(-d)}`, 'J0.');
    p.l('G03', `X${X(30)}`, `Y${f(-(8 - d))}`, 'I0.', `J${f(-(8 - d))}`);
    p.l('G02', `X${X(30 + d)}`, 'Y-8.', 'I0.', `J${f(-d)}`);
  }
  p.l('G01', 'Y-20.');
  p.l('G02', `X${X(20)}`, `Y${f(-30 - d)}`, `I${f(-(10 + d))}`, 'J0.');
  p.l('G01', `X${X(-20)}`);
  p.l('G02', `X${X(-20)}`, `Y${f(30 + d)}`, 'I0.', `J${f(30 + d)}`);
}

function contour() {
  const p = new Prog();
  const stock = { x: 120, y: 80, z: 25, label: 'aluminium 6061' };
  header(p, 1006, 'Complex contour - bracket outside profile', stock, ['T2 flat end mill D10 3FL']);
  const R = 5;
  const offsets = [33, 26, 19, 12];
  toolStart(p, 2, 2, 9500, 10 - 20, 30 + offsets[0] + R, 'Rough outside profile, 2.5 mm steps');
  p.l('Z2.');
  for (const z of [-2.5, -5, -7.5, -10]) {
    p.c(`Level Z${f(z)}`);
    p.l('G00', `X${f(-10)}`, `Y${f(30 + offsets[0] + R)}`);
    p.l('G01', `Z${f(z)}`, 'F600.');
    p.l('F1500.');
    for (const d of offsets) contourRing(p, d + 0, false, true);
    contourRing(p, R + 0.3, true, true); // semi-finish, 0.3 mm left
    p.l('G01', `Y${f(30 + offsets[0] + R)}`);
  }
  p.seq('Finish profile at full depth with arc lead-in');
  p.l('G00', `X${f(-10)}`, `Y${f(30 + R + 10)}`);
  p.l('G01', 'Z-10.', 'F600.');
  p.l('G01', `X${f(-10)}`, `Y${f(30 + R + 5)}`, 'F900.');
  p.l('G03', `X${f(-10 + 5)}`, `Y${f(30 + R)}`, 'I5.', 'J0.');
  contourRing(p, R, true, false);
  p.l('G01', `X${f(-10 + 5)}`, `Y${f(30 + R)}`);
  p.l('G03', `X${f(-10 + 10)}`, `Y${f(30 + R + 5)}`, 'I0.', 'J5.');
  toolEnd(p);
  p.l('M30');
  p.l('%');
  return { code: p.toString(), stock: { x: 120, y: 80, z: 25, material: 'aluminium', protrusion: 16 } };
}

// ---------------------------------------------------------------------------------------------
function fullPart() {
  const p = new Prog();
  const stock = { x: 120, y: 80, z: 30, label: 'aluminium 6061' };
  header(p, 1007, 'Complete part - automatic tool changes', stock, [
    'T1 face mill D50', 'T2 flat end mill D10', 'T4 spot drill D10', 'T5 drill D6.8', 'T8 chamfer mill D12',
  ]);
  // Op 1: face
  toolStart(p, 1, 1, 3200, -90, -25, 'Op 1 face 0.5 mm');
  p.l('Z2.');
  p.l('G01 Z-0.5 F800.');
  p.l('X90. F1300.');
  p.l('Y0.');
  p.l('X-90.');
  p.l('Y25.');
  p.l('X90.');
  toolEnd(p);
  p.blank();
  // Op 2: slotted pocket (stadium) 50 x 24 x 5
  toolStart(p, 2, 2, 9500, -20, 0, 'Op 2 stadium pocket 64 x 24 x 5 deep');
  p.l('Z2.');
  p.l('G01 Z-0.3 F700.');
  let z = -0.3;
  for (const depth of [-2, -3.5, -5]) {
    p.l('G01', 'X20.', `Z${f((z + depth) / 2)}`, 'F700.');
    p.l('X-20.', `Z${f(depth)}`);
    z = depth;
    p.l('X20. F1400.');
    p.l('X-20.');
    for (const r of [4, 7]) {
      p.l('G01', `Y${f(-r)}`);
      p.l('X20.');
      p.l('G03', 'X20.', `Y${f(r)}`, 'I0.', `J${f(r)}`);
      p.l('G01', 'X-20.');
      p.l('G03', 'X-20.', `Y${f(-r)}`, 'I0.', `J${f(-r)}`);
    }
    p.l('G01 Y0.');
  }
  toolEnd(p);
  p.blank();
  // Op 3: spot + drill four holes
  const holes = [[-45, -25], [45, -25], [45, 25], [-45, 25]];
  toolStart(p, 4, 4, 6000, holes[0][0], holes[0][1], 'Op 3 spot drill');
  p.l('G99', 'G81', `X${f(holes[0][0])}`, `Y${f(holes[0][1])}`, 'Z-4.', 'R2.', 'F500.');
  for (let i = 1; i < 4; i++) p.l(i === 3 ? 'G98' : '', `X${f(holes[i][0])}`, `Y${f(holes[i][1])}`);
  p.l('G80');
  toolEnd(p);
  p.blank();
  toolStart(p, 5, 5, 4500, holes[0][0], holes[0][1], 'Op 4 peck drill D6.8 x 20');
  p.l('G99', 'G83', `X${f(holes[0][0])}`, `Y${f(holes[0][1])}`, 'Z-20.', 'R2.', 'Q5.', 'F600.');
  for (let i = 1; i < 4; i++) p.l(i === 3 ? 'G98' : '', `X${f(holes[i][0])}`, `Y${f(holes[i][1])}`);
  p.l('G80');
  toolEnd(p);
  p.blank();
  // Op 5: chamfer the pocket edge with the 90 degree chamfer mill (1 mm chamfer)
  toolStart(p, 8, 8, 7000, -20, 0, 'Op 5 chamfer pocket edge 1 x 45');
  p.l('Z2.');
  // 90 deg cone: surface height = tip + radius. The top edge is at Z-0.5 after facing and the wall is
  // 12 mm from the pocket centre line, so a tool-centre offset of 9 and tip at Z-4.5 cuts a 1 x 45 chamfer
  // using the cone between radius 3 and 4, with the tip 0.5 mm clear of the pocket floor.
  const zc = -4.5;
  const rr = 9;
  p.l('G01', `Z${f(zc)}`, 'F500.');
  p.l('G01', 'X-20.', `Y${f(-rr)}`, 'F1200.');
  p.l('X20.');
  p.l('G03', 'X20.', `Y${f(rr)}`, 'I0.', `J${f(rr)}`);
  p.l('G01 X-20.');
  p.l('G03', 'X-20.', `Y${f(-rr)}`, 'I0.', `J${f(-rr)}`);
  p.l('G01 Y0.');
  toolEnd(p);
  p.l('G28 X0. Y0.');
  p.l('M30');
  p.l('%');
  return { code: p.toString(), stock: { x: 120, y: 80, z: 30, material: 'aluminium', protrusion: 14 } };
}

// ---------------------------------------------------------------------------------------------
// 3D surface: waterline-free roughing with a flat end mill that never gouges the surface (the tool
// height is the maximum of the surface under the whole cutter footprint), then a ball-nose raster.
function surfaceZ(x, y) {
  const r2 = x * x + y * y;
  return -9 + 7.5 * Math.exp(-r2 / 700) + 1.1 * Math.cos(x / 6.5) * Math.cos(y / 6.5) * Math.exp(-r2 / 2500);
}

function footprintMax(x, y, R, profile, leave) {
  let m = -Infinity;
  const n = 6;
  for (let i = -n; i <= n; i++) {
    for (let j = -n; j <= n; j++) {
      const dx = (i / n) * R, dy = (j / n) * R;
      const d2 = dx * dx + dy * dy;
      if (d2 > R * R) continue;
      const v = surfaceZ(x + dx, y + dy) - profile(Math.sqrt(d2)) + leave;
      if (v > m) m = v;
    }
  }
  return m;
}

function surface3d() {
  const p = new Prog();
  const stock = { x: 100, y: 80, z: 30, label: 'acetal POM' };
  header(p, 1008, '3D surface - roughing and ball-nose finishing', stock, ['T2 flat end mill D10', 'T6 ball end mill D8']);
  const X0 = -44, X1 = 44;
  toolStart(p, 2, 2, 9000, X0 - 8, -36, 'Roughing raster, 0.6 mm stock to leave');
  p.l('Z2.');
  const flat = () => 0;
  for (const level of [-3, -6, -9]) {
    p.c(`Roughing level Z${f(level)}`);
    let dir = 1;
    p.l('G00', `X${f(X0 - 8)}`, 'Y-36.');
    p.l('G01', `Z${f(level)}`, 'F600.');
    for (let y = -36; y <= 36 + 1e-9; y += 6) {
      p.l('G01', `Y${f(y)}`, 'F1800.');
      const xs = [];
      for (let x = X0 - 8; x <= X1 + 8 + 1e-9; x += 2) xs.push(x);
      if (dir < 0) xs.reverse();
      let lastZ = null;
      for (const x of xs) {
        const zz = Math.max(level, footprintMax(x, y, 5, flat, 0.6));
        const zr = Math.round(zz * 100) / 100;
        if (zr !== lastZ) p.l('G01', `X${f(x)}`, `Z${f(zr)}`);
        else p.l('G01', `X${f(x)}`);
        lastZ = zr;
      }
      dir = -dir;
    }
    p.l('G00 Z2.');
  }
  toolEnd(p);
  p.blank();
  const Rb = 4;
  const ball = (d) => Rb - Math.sqrt(Math.max(0, Rb * Rb - d * d));
  toolStart(p, 6, 6, 11000, X0 - 6, -38, 'Ball-nose finishing raster, 1.0 mm stepover');
  p.l('Z2.');
  p.l('G01 Z-9. F800.');
  let dir = 1;
  for (let y = -38; y <= 38 + 1e-9; y += 1.0) {
    p.l('G01', `Y${f(y)}`, 'F2200.');
    const xs = [];
    for (let x = X0 - 6; x <= X1 + 6 + 1e-9; x += 1.2) xs.push(x);
    if (dir < 0) xs.reverse();
    for (const x of xs) {
      const zz = Math.max(-9.5, footprintMax(x, y, Rb, ball, 0));
      p.l(`X${f(x)}`, `Z${f(zz)}`);
    }
    dir = -dir;
  }
  toolEnd(p);
  p.l('M30');
  p.l('%');
  return { code: p.toString(), stock: { x: 100, y: 80, z: 30, material: 'plastic', protrusion: 18 } };
}

export const EXAMPLES = [
  { id: 'facing', name: 'Simple facing', desc: 'Face mill skims 1 mm off the top in two zig-zag passes.', build: facing },
  { id: 'rect-pocket', name: 'Rectangular pocket', desc: 'Ramp entry, concentric roughing rings in 3 depth steps, finish pass with corner arcs.', build: rectPocket },
  { id: 'circ-pocket', name: 'Circular pocket', desc: 'Helical entry with G03 helices, spiral-out rings and a tangent arc finish pass in brass.', build: circPocket },
  { id: 'drilling', name: 'Drilling pattern', desc: 'Spot drill and peck drill a bolt circle and corner holes in steel using G81, G82, G83 and G73.', build: drilling },
  { id: 'slots', name: 'Slot milling', desc: 'Straight slots, a G02/G03 R50 arc slot and an incremental (G91) keyway in acetal.', build: slots },
  { id: 'contour', name: 'Complex contour', desc: 'Bracket outside profile with tangent arcs and a concave notch, roughed and finished.', build: contour },
  { id: 'full-part', name: 'Complete part (5 tools)', desc: 'Face, pocket, spot, drill and chamfer with automatic tool changes.', build: fullPart },
  { id: 'surface', name: '3D surface (ball nose)', desc: 'Roughing raster with a flat end mill, then a ball-nose finishing raster over a sculpted dome.', build: surface3d },
];

const cache = new Map();
export function getExample(id) {
  if (!cache.has(id)) {
    const ex = EXAMPLES.find((e) => e.id === id);
    if (!ex) return null;
    cache.set(id, { ...ex, ...ex.build() });
  }
  return cache.get(id);
}
